-- =============================================================
-- Datos de prueba (seed) — ProyectoClubes
-- Generado para SQL Server (T-SQL). Reproducible: random.seed(42).
--
-- Orden de carga respetado por dependencias de FK:
-- Cliente -> Espacio -> Reserva -> Pago -> Torneo -> Zona -> Equipo
-- -> Jugador -> Partido -> Evento_partido -> Deuda -> Gasto
--
-- Nota de escala: se pidieron ~100 filas por tabla. Se respeta esa
-- cantidad en las tablas transaccionales (Cliente, Reserva, Pago,
-- Jugador, Partido, Evento_partido, Deuda, Gasto). En las tablas
-- "catálogo" (Espacio, Torneo, Zona, Equipo) se usa una cantidad
-- realista para un complejo real (14 espacios, 3 torneos, 6 zonas,
-- 24 equipos) — 100 espacios o 100 torneos no reflejarían un caso de
-- uso real y complicarían la lectura de los datos de prueba.
--
-- Ajustar los nombres de tabla/columna si el esquema real del
-- backend difiere de docs/06-modelo-de-datos.md.
-- =============================================================

SET NOCOUNT ON;
BEGIN TRANSACTION;

